import numpy as np
from scipy.optimize import minimize
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
def nm(p,kind):
    a,b=p
    if kind=='pow': g=np.tanh(a*np.abs(t)**b)
    elif kind=='shift': g=np.tanh(a*(t+b))
    elif kind=='expo': g=1-np.exp(-a*np.abs(t)**b)
    X=np.column_stack([np.ones_like(t),P,P**2,P**3,g,g*P,g*P**2,g*P**3,t,t*P,t*P**2])
    c,_,_,_=np.linalg.lstsq(X,y,rcond=None)
    return np.mean((y-X@c)**2)/np.var(y)
for kind,p0 in [('pow',[0.25,1.0]),('pow',[0.5,0.8]),('shift',[0.23,0.0]),('expo',[0.3,1.0])]:
    r=minimize(lambda p: nm(p,kind),p0,method='Nelder-Mead',options={'xatol':1e-8,'fatol':1e-14,'maxiter':400})
    print(kind,p0,r.x,r.fun)
